// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != c.owner());
        bool ok;
        vm.prank(nonOwner);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
